import{MAX_GUESSES,normalize,evaluate,getBeijingDate,dailyIndex,gameStatus,searchSongs,searchSongMatches,validateLibrary,restoreGame}from'./core.js';
import{producersOf,vocalistsOf,peopleText,personTags,peopleCell}from'./people.js';
import{titleHint}from'./hints.js';
import{coverMarkup,installCoverFallback}from'./covers.js';
import{normalizeFilters,filterLibrary,filterKey,visibleCharts,filterDescription}from'./filters.js';
import{getLibrary,readFilters,setSettingsBusy}from'./app.js';
const $=s=>document.querySelector(s),platforms=['niconico','youtube'];
let activeFilters=normalizeFilters(),draftFilters=activeFilters;
const charts=()=>visibleCharts(activeFilters);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=v=>{try{const u=new URL(v);return u.protocol==='https:'?esc(u.href):'#'}catch{return'#'}};
const versionText=s=>s.versionLabel&&s.versionLabelKind!=='singing_credit_metadata'?' · 版本：'+s.versionLabel:'';
const labels={exact:'完全匹配',close:'部分匹配或接近',wrong:'不匹配',unknown:'暂缺可比较数据'};
let library,songs,byId,mode=document.body.dataset.mode==='practice'?'practice':'daily',today=getBeijingDate(),state,selectedId=null,results=[],focusIndex=-1,storageAvailable=true,busy=false;
function readStorage(key){try{return JSON.parse(localStorage.getItem(key)||'null')}catch{storageAvailable=false;return null}}
function save(){try{localStorage.setItem(storageKey(),JSON.stringify(state))}catch{storageAvailable=false}}
function storageKey(){return'chu-yiba:'+library.version+':'+filterKey(activeFilters)+':'+(mode==='daily'?'daily:'+today:'practice')}
function dailyAnswer(){return songs[dailyIndex(today,library.version+'|'+filterKey(activeFilters),songs.length)].id}
function randomAnswer(excluded){let pool=songs.filter(s=>s.id!==excluded);if(!pool.length)pool=songs;return pool[Math.floor(Math.random()*pool.length)].id}
function loadState(){const fallback=mode==='daily'?dailyAnswer():randomAnswer(),saved=readStorage(storageKey());state={...restoreGame(saved,songs,fallback),views:{},playbackRevision:typeof saved?.playbackRevision==='string'?saved.playbackRevision:library.playbackUpdate?.revision||null};if(mode==='daily'&&state.answerId!==fallback){state={answerId:fallback,guesses:[],views:{},playbackRevision:library.playbackUpdate?.revision||null};return}if(saved?.views)for(const id of [state.answerId,...state.guesses]){const record=saved.views[id];if(!record||typeof record!=='object')continue;state.views[id]={};for(const p of platforms){const v=record[p];if(['ok','stale'].includes(v?.status)&&Number.isSafeInteger(v.count)&&v.count>=0&&typeof v.fetchedAt==='string'&&Number.isFinite(Date.parse(v.fetchedAt)))state.views[id][p]={status:v.status,count:v.count,fetchedAt:v.fetchedAt,snapshotAt:v.snapshotAt||null};else if(['error','unavailable','unlinked','no_official'].includes(v?.status)&&v.count===null)state.views[id][p]={status:v.status,count:null,fetchedAt:typeof v.fetchedAt==='string'?v.fetchedAt:null};}}}
const status=()=>gameStatus(state.guesses,state.answerId),message=t=>$('#feedback-message').textContent=t;
function hideSuggestions(){results=[];focusIndex=-1;$('#suggestions').hidden=true;$('#song-search').setAttribute('aria-expanded','false');$('#song-search').removeAttribute('aria-activedescendant')}
function renderSelection(song){const panel=$('#selected-song');panel.hidden=!song;panel.innerHTML=song?coverMarkup(song,{variant:'selected',lazy:false})+'<span class="selected-song-copy"><span class="selected-song-label">待确认的歌曲</span><strong>'+esc(song.title)+'</strong><small>'+song.year+' 年'+esc(versionText(song))+'</small></span>':''}
function clearSearch(){selectedId=null;renderSelection(null);$('#song-search').value='';$('#clear-search').hidden=true;hideSuggestions();$('#input-help').textContent='支持译名、罗马音、P 主别名和歌姬中文名。'}
function selectSong(id){const s=byId.get(id);if(!s||state.guesses.includes(id)||status()!=='playing'||busy)return;selectedId=id;renderSelection(s);$('#song-search').value=s.title;$('#clear-search').hidden=false;$('#input-help').textContent=peopleText(s);message('');hideSuggestions();$('#song-search').focus()}
function showSuggestions(){if(status()!=='playing'||busy)return;const matches=searchSongMatches(songs,$('#song-search').value,state.guesses).slice(0,12);results=matches.map(m=>m.song);focusIndex=-1;$('#suggestions').innerHTML=matches.length?matches.map(({song:s,matchedAlias,matchKind,matchType},i)=>'<div class="suggestion" id="song-option-'+i+'" role="option" aria-selected="false" data-id="'+esc(s.id)+'">'+coverMarkup(s,{lazy:false})+'<span class="suggestion-copy"><span class="suggestion-title">'+esc(s.title)+'</span>'+(matchedAlias&&normalize(matchedAlias)!==normalize(s.title)?'<span class="suggestion-alias">'+(matchKind==='producer'?'匹配作者：':matchKind==='singer'?'匹配歌姬：':matchType==='suggested'?'你可能想找：':'匹配别名：')+esc(matchedAlias)+'</span>':'')+'<span class="suggestion-sub">'+personTags(producersOf(s))+' · '+personTags(vocalistsOf(s))+esc(versionText(s))+'</span></span><span class="suggestion-year">'+s.year+'</span></div>').join(''):'<div class="no-suggestions">当前曲库没有找到歌曲。试试中文译名、英文名、罗马音、P 主别名或歌姬，也可放宽曲库和年份条件。</div>';$('#suggestions').hidden=false;$('#song-search').setAttribute('aria-expanded','true')}
function focusOption(index){if(!results.length)return;focusIndex=(index+results.length)%results.length;$('#suggestions').querySelectorAll('.suggestion').forEach((el,i)=>{el.classList.toggle('focused',i===focusIndex);el.setAttribute('aria-selected',String(i===focusIndex))});const el=$('#song-option-'+focusIndex);$('#song-search').setAttribute('aria-activedescendant',el.id);el.scrollIntoView({block:'nearest'})}
const feedback=id=>evaluate(byId.get(id),byId.get(state.answerId),state.views[id],state.views[state.answerId]);
const count=n=>n>=1e8?(n/1e8).toFixed(2)+'亿':n>=1e4?(n/1e4).toFixed(1)+'万':n.toLocaleString('zh-CN');
const time=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'';
function cell(value,result,note='',title=''){const s=typeof result==='string'?result:result.status;return'<td class="'+s+'"'+(title?' title="'+esc(title)+'"':'')+' aria-label="'+esc(value+'，'+labels[s]+(note?'，'+note:'')+(title?'；'+title:''))+'">'+esc(value)+(typeof result==='object'&&result.direction?'<span class="direction" aria-hidden="true">'+(result.direction==='up'?'↑':'↓')+'</span>':'')+'<span class="cell-note" aria-hidden="true">'+esc(note||({exact:'✓ 匹配',close:'≈ 部分匹配',wrong:'× 不匹配',unknown:'暂无判定'}[s]))+'</span></td>'}
function numberCell(value,result,kind,title=''){const direction=result.direction==='up'?(kind==='year'?'更晚':kind==='peak'?'更靠前':'更多'):result.direction==='down'?(kind==='year'?'更早':kind==='peak'?'更靠后':'更少'):'不匹配';const note=result.status==='unknown'?'数据暂缺':result.status==='exact'?'✓ 匹配':(result.status==='close'?'≈ 接近 · ':'')+direction;return cell(value,result,note,title)}
function viewCell(song,p,result){const v=state.views[song.id]?.[p];if(['ok','stale'].includes(v?.status)){const markup=numberCell(count(v.count),result,'views',v.count.toLocaleString('zh-CN')+' 次；'+(p==='niconico'?'官方快照 '+time(v.snapshotAt):'读取于 '+time(v.fetchedAt))+(v.status==='stale'?'；更新暂失败，保留最近成功数据':'')+'（本局固定）');return v.status==='stale'?markup.replace('</td>','<span class="cell-note">最近成功数据</span></td>'):markup}return cell(v?.status==='unavailable'?'原投稿失效':v?.status==='error'?'读取失败':'暂无数据',result,v?.status==='error'?'可重试读取':v?.status==='unavailable'?'不参与判定':v?.status==='no_official'?'作者无官方投稿':song.videos[p]?'快照未收录':'官方链接待核实')}
function chartSummary(r){return r.status==='complete'?r.weeks+' 周 / '+(r.peak===null?'未上榜':'最高第 '+r.peak+' 名'):'暂无数据（官方原投稿待核实）'}
function chartCell(song,c,key,result){const r=song.rankings[c];if(r.status!=='complete')return cell('暂无数据',result,r.reason==='original_unconfirmed'?'官方原投稿待核实':r.knownWeeks>0?(key==='weeks'?'已记录 '+r.knownWeeks+' 周':'已记录最高第 '+r.knownPeak+' 名'):'暂无可核对的主榜记录');const value=key==='weeks'?r.weeks+' 周':r.peak===null?'未上榜':'第 '+r.peak+' 名';const answer=byId.get(state.answerId).rankings[c];if(key==='peak'&&result.status==='wrong'&&!result.direction&&answer.status==='complete')return cell(value,result,answer.peak===null?'答案未进入主榜':'答案有主榜名次');return numberCell(value,result,key)}
function songCell(song,feedback){const note=feedback==='exact'?'✓ 正是这首':'第 '+(state.guesses.indexOf(song.id)+1)+' 次猜测'+versionText(song);return '<td class="'+feedback+'" aria-label="'+esc(song.title+'，'+labels[feedback]+'，'+note)+'"><div class="song-entry">'+coverMarkup(song)+'<span class="song-name">'+esc(song.title)+'</span></div><span class="cell-note">'+esc(note)+'</span></td>'}
function rowMarkup(id){const s=byId.get(id),f=feedback(id);return'<tr>'+songCell(s,f.song)+peopleCell(f.producerDetails)+peopleCell(f.singerDetails)+numberCell(String(s.year),f.year,'year')+platforms.map(p=>viewCell(s,p,f.views[p])).join('')+charts().flatMap(c=>['weeks','peak'].map(k=>chartCell(s,c,k,f[c][k]))).join('')+'</tr>'}
function renderResult(){const panel=$('#result-panel'),current=status();panel.hidden=current==='playing';if(panel.hidden){panel.innerHTML='';return}const s=byId.get(state.answerId),won=current==='won';panel.classList.toggle('lost',!won);const links=platforms.filter(p=>s.videos[p]).map(p=>'<a href="'+url(s.videos[p].url)+'" target="_blank" rel="noopener noreferrer">'+p+' 原投稿</a>').join(''),counts=platforms.map(p=>{const v=state.views[s.id]?.[p];return p+'：'+(['ok','stale'].includes(v?.status)?v.count.toLocaleString('zh-CN')+' 次（'+time(p==='niconico'?(v.snapshotAt||v.fetchedAt):v.fetchedAt)+'）':v?.status==='error'?'读取失败':v?.status==='unavailable'?'原投稿失效':'暂无数据')}).join('<br>'),chartText=charts().map(c=>{const r=s.rankings[c];return(c==='billboard'?'周榜':'周刊总榜')+'：'+chartSummary(r)}).join('<br>');panel.innerHTML='<h3>'+(won?'猜中了！':'答案揭晓')+'</h3><div class="result-song">'+coverMarkup(s,{variant:'result',lazy:false})+'<p><strong>'+esc(s.title)+'</strong>'+(versionText(s)?'<br><span class="result-version">'+esc(versionText(s).slice(3))+'</span>':'')+'<br>'+personTags(producersOf(s))+' feat. '+personTags(vocalistsOf(s))+'<br>'+s.year+(won?' · '+state.guesses.length+' / '+MAX_GUESSES+' 次猜中':' · '+MAX_GUESSES+' 次机会已用完')+'</p></div><details class="result-details"><summary>播放量与榜单记录</summary><p class="result-data">'+counts+'<br>'+chartText+'</p></details><div class="result-links">'+links+'<a href="'+url(s.source)+'" target="_blank" rel="noopener noreferrer">核对歌曲资料</a></div><div class="result-actions"><button class="secondary-button" id="copy-result">复制战绩</button><button class="primary-button" id="next-song">'+(mode==='daily'?'进入单人模式':'再猜一首')+'</button></div>'}
function visibleHint(){return titleHint(byId.get(state.answerId).title,state.guesses.length,storageKey()+'|'+state.answerId,status()!=='playing')}
function renderHints(){const h=visibleHint(),ended=status()!=='playing';$('#hint-count').textContent=h.characterCount+' 字';$('#hint-sequence').setAttribute('aria-label','标题提示：'+h.maskedTitle);$('#hint-sequence').innerHTML=h.tokens.map(t=>'<span aria-hidden="true" class="'+(t.kind==='space'?'hint-space':'hint-glyph '+t.kind+(t.revealed?' revealed':''))+'">'+esc(t.text)+'</span>').join('');$('#hint-status').textContent=ended?'曲名已揭晓':h.revealedCount?'已揭示 '+h.revealedCount+' 字':'空格不计数';$('#hint-producer').hidden=!h.producerUnlocked;$('#hint-producer').innerHTML=h.producerUnlocked?'<span>这首歌的 P 主</span>'+personTags(producersOf(byId.get(state.answerId))):'';$('#hint-stages').innerHTML=[[3,'1 字'],[6,'再 3 字'],[9,'P 主']].map(([n,label])=>'<span class="'+(state.guesses.length>=n||ended?'unlocked':'')+'"><b>'+n+'</b> 次 · '+label+'</span>').join('')}
function render(){const daily=mode==='daily',current=status();document.querySelectorAll('.mode').forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.disabled=busy});$('#game-date').textContent=daily?today.replaceAll('-',' / '):'随机曲目';$('#game-heading').textContent=daily?'每日挑战':'单人模式';$('#attempt-count').innerHTML=state.guesses.length+' <span>/ '+MAX_GUESSES+'</span>';$('#attempt-track').innerHTML=Array.from({length:MAX_GUESSES},(_,i)=>'<i class="'+(i<state.guesses.length?'used ':'')+(current==='won'&&i<state.guesses.length?'won':'')+'"></i>').join('');renderHints();$('#guess-rows').innerHTML=state.guesses.map(rowMarkup).join('');$('#empty-board').hidden=state.guesses.length>0;updateBoardNote();renderPlaybackDetails();$('#song-search').disabled=current!=='playing'||busy;$('#guess-submit').disabled=current!=='playing'||busy;$('#guess-submit').textContent=busy?'读取中…':'猜这首';$('#new-practice').disabled=busy;$('#new-practice').hidden=daily;$('#retry-views').disabled=busy;$('#retry-views').hidden=state.guesses.length===0||![state.answerId,...state.guesses].some(id=>platforms.some(p=>byId.get(id).videos[p]&&!['ok','stale'].includes(state.views[id]?.[p]?.status)));$('#local-note').textContent=storageAvailable?'进度保存在本机':'本次进度无法保存，请勿关闭页面';setSettingsBusy(busy);renderResult();if(busy)$('#next-song')?.setAttribute('disabled','')}
async function loadViews(ids){const needed=[...new Set(ids)].filter(id=>platforms.some(p=>byId.get(id).videos[p]&&state.views[id]?.[p]?.status!=='ok'));if(!needed.length)return;let data;try{const r=await fetch('/api/views?songs='+encodeURIComponent(needed.join(','))+(state.playbackRevision?'&revision='+encodeURIComponent(state.playbackRevision):state.views[state.answerId]?.niconico?.snapshotAt?'&snapshot='+encodeURIComponent(state.views[state.answerId].niconico.snapshotAt):''),{signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error('服务暂时无法读取');const payload=await r.json();state.playbackRevision??=payload.revision||null;data=payload.songs;}catch{data=Object.fromEntries(needed.map(id=>[id,Object.fromEntries(platforms.map(p=>[p,{status:byId.get(id).videos[p]?'error':'unlinked',count:null,fetchedAt:null}]))]));}for(const id of needed){state.views[id]??={};for(const p of platforms){if(['ok','stale'].includes(state.views[id][p]?.status))continue;state.views[id][p]=data[id]?.[p]||{status:'error',count:null,fetchedAt:null};}}}
async function submitGuess(id){if(typeof id!=='string'||!byId.has(id))throw new Error('请从曲库中选择一首歌曲。');if(busy)throw new Error('正在读取线索，请稍候。');if(status()!=='playing')throw new Error('本局已经结束，可以开始自由练习。');if(state.guesses.includes(id))throw new Error('这首歌已经猜过了，试试另一首。');busy=true;hideSuggestions();render();message('正在读取播放量…');try{await loadViews([id,state.answerId]);state.guesses.push(id);save();clearSearch();busy=false;render();const current=status();message(current==='won'?'猜中了！':current==='lost'?'机会已用完，答案已揭晓。':'第 '+state.guesses.length+' 次猜测，线索已更新。');if(current!=='playing')$('#result-panel').focus();return{status:current,attempts:state.guesses.length,feedback:feedback(id)};}finally{busy=false;render()}}
function switchMode(next){if(busy)throw new Error('请等待线索读取完成');if(!['daily','practice'].includes(next))throw new Error('未知的游戏模式');if(mode===next)return;mode=next;loadState();clearSearch();message('');render()}
function newPractice(){if(busy)throw new Error('请等待线索读取完成');if(mode==='daily'){location.assign('/single');return{navigation:'/single'};}const old=state?.answerId;mode='practice';state={answerId:randomAnswer(old),guesses:[],views:{},playbackRevision:library.playbackUpdate?.revision||null};save();clearSearch();render();message('新的一首，开始吧。');$('#song-search').focus();return{mode,status:'playing',attempts:0}}
function stateView(){return{mode,filters:activeFilters,songCount:songs.length,charts:charts(),date:mode==='daily'?today:null,maxGuesses:MAX_GUESSES,status:status(),busy,hints:{...visibleHint(),...(visibleHint().producerUnlocked?{producers:producersOf(byId.get(state.answerId)).map(p=>({id:p.id,name:p.name}))}:{})},guesses:state.guesses.map(id=>({id,title:byId.get(id).title,versionLabel:byId.get(id).versionLabel||null,views:state.views[id],feedback:feedback(id)})),...(status()==='playing'?{}:{answer:{id:state.answerId,title:byId.get(state.answerId).title,views:state.views[state.answerId]}})}}
async function copyResult(){const squares={exact:'🟩',close:'🟨',wrong:'⬛',unknown:'⬜'},lines=state.guesses.map(id=>{const f=feedback(id);return[f.song,f.producer,f.singers,f.year.status,...platforms.map(p=>f.views[p].status),...charts().flatMap(c=>[f[c].weeks.status,f[c].peak.status])].map(s=>squares[s]).join('')});const text='初一把 · '+(mode==='daily'?today:'自由练习')+'\n'+filterLabel()+'\n'+(status()==='won'?state.guesses.length:'X')+'/'+MAX_GUESSES+'\n'+lines.join('\n')+'\n歌曲 / P主 / 歌姬 / 年份 / Nico / YT / '+charts().map(c=>c==='billboard'?'周榜周数·名次':'周刊周数·名次').join(' / ');try{await navigator.clipboard.writeText(text);message('战绩已复制，分享时不会显示歌名。')}catch{message('浏览器未允许复制，请手动复制下方战绩。');const pre=document.createElement('pre');pre.textContent=text;pre.style.whiteSpace='pre-wrap';$('#result-panel').append(pre)}}
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),defs=[{name:'get_game_state',description:'Read visible game clues, including view counts and timestamps. Answer only revealed after round end.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>stateView()},{name:'search_songs',description:'Search the vocal synth library without consuming an attempt.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(typeof input?.query!=='string')throw new Error('query must be a string');return searchSongs(songs,input.query,state.guesses).slice(0,12).map(s=>({id:s.id,title:s.title,versionLabel:s.versionLabel||null,producer:s.producer,producers:producersOf(s).map(p=>p.name),singers:s.singers,year:s.year}))}},{name:'submit_song_guess',description:'Guess a library song, read official platform view counts, and consume one of ten attempts.',inputSchema:{type:'object',properties:{songId:{type:'string'}},required:['songId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.songId!=='string')throw new Error('songId must be a string');return submitGuess(input.songId)}},{name:'start_new_practice',description:'Start a random new practice round. Daily progress preserved.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>newPractice()}];for(const tool of defs)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
function renderCredits(){
 const b=library.charts.billboard,w=library.charts.weekly;
 $('#snapshot-note').textContent='周榜截至 '+b.through+' · 周刊 #'+w.fromEpisode+'–#'+w.throughEpisode+' 总榜 · Nico 与 YouTube 每周一 07:00（北京时间）统一更新，本局固定';
 $('#chart-sources').innerHTML='<p><a href="https://www.billboard-japan.com/charts/detail/?a=niconico" target="_blank" rel="noopener noreferrer">Billboard 官方主榜</a>：'+b.from+' — '+b.through+'，'+b.periods+' 期 TOP20。</p><p><a href="'+url(w.latestEvidenceUrl||w.source)+'" target="_blank" rel="noopener noreferrer">周刊总榜与最新发布记录</a>：#'+w.fromEpisode+'–#'+w.throughEpisode+'，旧制 TOP30、新制总榜 TOP10；排除新曲榜、UTAU 榜和 History。'+(w.publicationNote?esc(w.publicationNote):'')+'</p><p>播放量 Top100 仅在已收录并核实的歌曲中排名。Nico 数据时间 '+time(library.collectionSources.playbackRanking.niconicoSnapshotAt)+'。未确认官方原投稿时显示暂无数据。</p><p>译名优先采用作者在国内平台的官方投稿，其次是百科、国内音乐平台和其他网络别名；日语歌名与 P 主读音也用于罗马音联想。P 主别名与歌姬中文名可搜索，歌姬标签使用官方原名。</p>';
 $('#credits-list').innerHTML=songs.slice(0,100).map(s=>'<div class="credit-row"><span>'+esc(s.title)+'<small>'+personTags(producersOf(s))+' · '+personTags(vocalistsOf(s))+' · '+s.year+'</small><span class="credit-detail">周榜：'+chartSummary(s.rankings.billboard)+'<br>周刊：'+chartSummary(s.rankings.weekly)+'</span><span class="video-links">'+platforms.filter(p=>s.videos[p]).map(p=>'<a href="'+url(s.videos[p].url)+'" target="_blank" rel="noopener noreferrer">'+p+' 原投稿</a>').join('')+'</span></span><a href="'+url(s.source)+'" target="_blank" rel="noopener noreferrer">歌曲资料</a></div>').join('')+(songs.length>100?'<p class="dialog-note">当前范围共 '+songs.length+' 首，此处列出前 100 首；全部歌曲均可在游戏搜索中查询。</p>':'');
}

function filterSummary(){return filterDescription(activeFilters)+' · '+songs.length+' 首'}
function updateBoardNote(){const table=$('.table-scroll');$('#board-note').textContent=table.scrollWidth>table.clientWidth+1?'左右滑动查看全部线索':''}
function renderPlaybackDetails(){const note=$('#playback-note');note.innerHTML='<span>播放量首次读取成功后在本局固定。</span>'+(state.guesses.length?'<ul class="playback-records">'+state.guesses.map(id=>{const song=byId.get(id);return '<li><strong>'+esc(song.title)+'</strong>'+platforms.map(p=>{const v=state.views[id]?.[p],text=['ok','stale'].includes(v?.status)?v.count.toLocaleString('zh-CN')+' 次 · '+time(p==='niconico'?(v.snapshotAt||v.fetchedAt):v.fetchedAt)+(v.status==='stale'?' · 最近成功数据':''):v?.status==='error'?'读取失败':v?.status==='unavailable'?'原投稿失效':'暂无数据';return '<span>'+p+'：'+esc(text)+'</span>'}).join('')+'</li>'}).join('')+'</ul>':'')}

function filterLabel(){return filterSummary()}
function renderHeaders(){const names={billboard:'周榜',weekly:'周刊总榜'};$('#clue-columns').innerHTML='<col class="song-col"><col><col><col class="year-col"><col><col>'+charts().map(()=>'<col><col>').join('');$('#clue-header').innerHTML='<tr class="column-groups"><th colspan="4" scope="colgroup">歌曲信息</th><th colspan="2" scope="colgroup">播放量</th>'+charts().map(c=>'<th colspan="2" scope="colgroup">'+names[c]+'</th>').join('')+'</tr><tr>'+['歌曲','P 主','歌姬','年份','niconico','YouTube',...charts().flatMap(()=>['在榜周数','最高名次'])].map(n=>'<th scope="col">'+n+'</th>').join('')+'</tr>';$('#clue-table').classList.toggle('one-chart',charts().length===1)}
function updatePoolUI(){$('#library-count').textContent=library.songs.length;$('#active-filter-summary').textContent=filterSummary();$('.library-footnote').textContent=filterLabel();$('#starter-chips').innerHTML=songs.slice(0,3).map(s=>'<button type="button" class="starter-chip" data-id="'+esc(s.id)+'">'+esc(s.title)+'</button>').join('');renderHeaders();renderCredits()}
function applyFilters(next){if(busy||!library)return;next=normalizeFilters(next);const pool=filterLibrary(library.songs,next);if(!pool.length||filterKey(next)===filterKey(activeFilters))return;save();activeFilters=next;songs=pool;byId=new Map(songs.map(s=>[s.id,s]));loadState();clearSearch();updatePoolUI();render();message('曲库已切换：'+songs.length+' 首。');}
function initFilters(){activeFilters=readFilters();if(!filterLibrary(library.songs,activeFilters).length)activeFilters=normalizeFilters();songs=filterLibrary(library.songs,activeFilters);byId=new Map(songs.map(s=>[s.id,s]));}
window.addEventListener('chu-settings-change',e=>applyFilters(e.detail));

async function init(){try{library=await getLibrary();initFilters();loadState();updatePoolUI();render();
$('#song-search').addEventListener('input',()=>{selectedId=null;renderSelection(null);$('#clear-search').hidden=!$('#song-search').value;showSuggestions();message('')});$('#song-search').addEventListener('focus',()=>{if(!selectedId&&$('#song-search').value.trim())showSuggestions()});$('#song-search').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape')hideSuggestions();else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if($('#suggestions').hidden)showSuggestions();focusOption(focusIndex+(e.key==='ArrowDown'?1:-1))}else if(e.key==='Enter'&&!$('#suggestions').hidden&&focusIndex>=0){e.preventDefault();selectSong(results[focusIndex].id)}});$('#suggestions').addEventListener('click',e=>{const o=e.target.closest('.suggestion');if(o)selectSong(o.dataset.id)});document.addEventListener('click',e=>{if(!$('#guess-form').contains(e.target))hideSuggestions()});$('#clear-search').addEventListener('click',()=>{clearSearch();$('#song-search').focus()});$('#guess-form').addEventListener('submit',async e=>{e.preventDefault();if(!selectedId){const matches=songs.filter(s=>[s.title,...s.aliases].some(n=>normalize(n)===normalize($('#song-search').value)));if(matches.length===1)selectedId=matches[0].id}try{await submitGuess(selectedId)}catch(error){message(error.message)}});$('#starter-chips').addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectSong(b.dataset.id)});document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>switchMode(b.dataset.mode)));$('#new-practice').addEventListener('click',newPractice);$('#result-panel').addEventListener('click',e=>{if(e.target.closest('#next-song'))newPractice();if(e.target.closest('#copy-result'))void copyResult()});$('#retry-views').addEventListener('click',async()=>{busy=true;render();message('正在重试暂缺的播放量…');await loadViews([state.answerId,...state.guesses]);busy=false;save();render();message('已重试读取播放量。')});setInterval(()=>{const date=getBeijingDate();if(date===today||busy)return;today=date;if(mode==='daily'){loadState();clearSearch();render();message('北京时间已到新一天，今日题目已更新。')}},60000);registerWebMCP();
}catch(error){$('#game-heading').textContent='曲库暂时未能载入';message('请刷新页面重试。'+error.message);$('#song-search').disabled=true;$('#guess-submit').disabled=true;$('#empty-board').querySelector('strong').textContent='等待曲库载入'}}
function openDialog(s){hideSuggestions();$(s).showModal()}
$('#rules-open').addEventListener('click',()=>openDialog('#rules-dialog'));$('#credits-open').addEventListener('click',()=>openDialog('#credits-dialog'));window.addEventListener('resize',()=>{if(library)updateBoardNote()});installCoverFallback(document,id=>byId?.get(id));void init();
